<?php $title = 'گزارش فروش'; ?>
<div class="card"><form class="actions" method="get" action="<?= e(base_url('accounting/sales-report')) ?>"><button class="btn <?= $group==='daily'?'':'light' ?>" name="group" value="daily">فروش روزانه</button><button class="btn <?= $group==='monthly'?'':'light' ?>" name="group" value="monthly">فروش ماهانه</button></form></div>
<div class="card"><h2><?= $group==='monthly'?'گزارش ماهانه':'گزارش روزانه' ?></h2><div class="table-wrap"><table class="table"><tr><th>دوره</th><th>تعداد فاکتور</th><th>فروش</th><th>بهای تمام‌شده</th><th>سود ناخالص</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['period']) ?></td><td><?= e($r['invoice_count']) ?></td><td><?= e(number_format((float)$r['total'])) ?></td><td><?= e(number_format((float)$r['cost'])) ?></td><td><?= e(number_format((float)$r['gross_profit'])) ?></td></tr><?php endforeach; ?></table></div></div>
